		void UpdateParametersGroupBoxesVisibility()
		{
			if (ParametersPanel != null)
			{
				var warehouse = Warehouse;
				if (warehouse != null)
				{
					var isProductWarehouse = warehouse.WW_WarehouseType.EqualsIgnoringCase(WarehouseTypes.Codes.Product);
					var isFreeTradeZoneWarehouse = warehouse.WW_WarehouseType.EqualsIgnoringCase(WarehouseTypes.Codes.FreeTradeZone);
					AutoPrintGroupBox.Visible = isProductWarehouse || isFreeTradeZoneWarehouse;
					ABCAnalysisGroupBox.Visible = isProductWarehouse || isFreeTradeZoneWarehouse;
					PackageIDsGroupBox.Visible = isProductWarehouse || isFreeTradeZoneWarehouse;
					FinalisedDateGroupBox.Visible = isProductWarehouse || isFreeTradeZoneWarehouse;
					PickPackGroupBox.Visible = isProductWarehouse || isFreeTradeZoneWarehouse;
					VerifyEmptyLocationsGroupBox.Visible = isProductWarehouse || isFreeTradeZoneWarehouse;
					IsPickByUOMGroupBox.Visible = isProductWarehouse || isFreeTradeZoneWarehouse;
					RFGroupBox.Visible = isProductWarehouse || isFreeTradeZoneWarehouse;
					ReleasingGroupBox.Visible = isProductWarehouse || isFreeTradeZoneWarehouse;

					var isContainerYard = warehouse.WW_WarehouseType.EqualsIgnoringCase(WarehouseTypes.Codes.ContainerYard);
					VehicleBookingIntegrationGroupBox.Visible = isContainerYard;

					var isTransitWarehouse = warehouse.WW_WarehouseType.EqualsIgnoringCase(WarehouseTypes.Codes.Transit);
					TransitSecurityGroupBox.Visible = isTransitWarehouse;
					TransitLoadingGroupBox.Visible = isTransitWarehouse;

					UpdateDetailedTrackingVisibility(warehouse);
					UpdateCycleCountGroupBoxVisibility(isTransitWarehouse, isProductWarehouse);
					UpdateDockDoorGroupBoxVisibility(isTransitWarehouse, isProductWarehouse || isFreeTradeZoneWarehouse);
					UpdateTaskManagementGroupBoxVisibility(isProductWarehouse || isFreeTradeZoneWarehouse);
					UpdateCustomsGroupBoxVisibility(isTransitWarehouse);
					UpdateLocationComponentDelimiterTextBoxCaption();
				}
			}
		}

		void UpdateDetailedTrackingVisibility(WhsWarehouse warehouse)
		{
			if (ParametersPanel != null && warehouse != null)
			{
				DetailedTrackingGroupBox.Visible = warehouse.IsFTZWarehouseInCountryThatUsesPermits;
			}
		}

		void UpdateDockDoorGroupBoxVisibility(bool isTransitWarehouse, bool dockDoorGroupVisible)
		{
			if (isTransitWarehouse)
