				DefaultOutboundDoorFindBox.Visible = false;
				DockDoorGroupBox.Location = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledPoint(3, 424, true);
				DockDoorGroupBox.Size = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledSize(350, 70, true);
				DockDoorGroupBox.Visible = true;
			}
			else
			{
				DefaultOutboundDoorFindBox.Visible = true;
				DockDoorGroupBox.Location = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledPoint(375, 374, true);
				DockDoorGroupBox.Size = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledSize(350, 109, true);
				DockDoorGroupBox.Visible = dockDoorGroupVisible;
			}
		}

		void UpdateCycleCountGroupBoxVisibility(bool isTransitWarehouse, bool isProductWarehouse)
		{
			if (isTransitWarehouse)
			{
				CycleCountGroupBox.Location = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledPoint(3, 495, true);
				CycleCountGroupBox.Visible = true;
