			else if (isProductWarehouse)
			{
				CycleCountGroupBox.Location = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledPoint(3, 545, true);
				CycleCountGroupBox.Visible = true;
			}
			else
			{
				CycleCountGroupBox.Visible = false;
			}
		}

