		[SuppressMessage("CargoWiseOne", "CW1079:DoNotCompareOnExceptionMessage", Justification = "Exception message is not translatable")]
		protected override void HandleSaveException(Exception e)
		{
			if (e is ZSaveException
				&& e.InnerException != null &&
				e.InnerException.InnerException != null &&
				e.InnerException.InnerException.Message == WhsWarehouse.CannotChangeWarehouseTypeToOrFromTransitIfAlreadyReferencedTriggerID) // SuppressCodeSmell Reason = Exception message is not translatable
			{
				Globals.Message.ShowError(Res.GetString("84db060d-5363-410b-9f71-7237f07d16e1", "Cannot Change Warehouse Type as this Warehouse is already in use."));
			}
			else
			{
				base.HandleSaveException(e);
			}
		}

